/** Response with today's planned training session(s). */
export interface GetTodaySessionResponse {
    /** Whether there is at least one session planned for today. */
    hasSession?: boolean;
    /** The training plan's public ID. */
    planId?: string | undefined;
    /** The plan name. */
    planName?: string | undefined;
    /** All training sessions scheduled for today, ordered by Order.
Empty when there are none. */
    sessions?: TrainingSession[];
    /** The first training session for today, if any.
Deprecated: use Sessions instead. This property mirrors
Sessions[0] (or null when empty) and is kept for backwards
compatibility with consumers that still reference the singular session. */
    session?: TrainingSession | undefined;
    /** Current week number in the plan cycle. */
    currentWeek?: number | undefined;
    /** Total number of weeks in the plan. */
    totalWeeks?: number | undefined;
    /** Plan status (Active, Completed, Archived). */
    status?: string | undefined;
    /** Linked questionnaire response public ID, if any. */
    questionnaireResponseId?: string | undefined;
    /** When this plan was marked as completed, if applicable. */
    dateCompleted?: string | undefined;
    /** Last day of the plan's last published week, set only when the plan's coach no longer has a plan that covers
this client: after it the plan is read-only. Null otherwise. */
    runsUntil?: string | undefined;
    /** Per-exercise muscle groups, keyed by SessionExercise.ExerciseExternalId.
Empty when an exercise no longer exists in the database. Populated by
looking up Exercise documents for every exercise referenced by today's
sessions. */
    exerciseMuscleGroups?: { [key: string]: MuscleGroup[]; };
    /** Per-session completed exercise IDs, keyed by SessionId. Sourced from
TrainingCompletion documents for today. Empty dictionary when no session
has any completed exercise for today (or when no active plan exists).
Deprecated. Use CompletedExerciseIdsByWorkoutAndSession for
workout-aware completion tracking. This field is retained for backward compatibility
with mobile and web clients that have not yet migrated to the new field. */
    completedExerciseIdsBySession?: { [key: string]: string[]; };
    /** Workout-aware completed exercise IDs for today.
Outer key = SessionId, inner key = WorkoutId, value = list of completed ExerciseExternalIds
within that workout.
Sourced from TrainingCompletion documents with read-time backfill for legacy data.
Empty dictionary when no exercises have been completed for today. */
    completedExerciseIdsByWorkoutAndSession?: { [key: string]: { [key: string]: string[]; }; };
    /** Per-session completed workout IDs, keyed by SessionId. Sourced from
TrainingCompletion documents for today. Empty dictionary when no
workout has been workout-completed for today (or no active plan exists).
Workouts appear here when the client tapped a workout-level checkbox
(e.g. on a ForTime "Running" workout that has no exercises) or when
MarkSessionComplete fanned out workout IDs. */
    completedWorkoutIdsBySession?: { [key: string]: string[]; };
    /** Per-session optimistic-concurrency version numbers for today, keyed by SessionId.
Matches the Version on the TrainingCompletion document. Used by the client to
send the If-Match-style version header on subsequent mark/unmark requests.
Missing entries imply a fresh document (server will accept Version=null/1). */
    versionBySession?: { [key: string]: number; };
    /** Per-session, per-exercise completed set numbers for today. Keyed by
SessionId → ExerciseExternalId → list of 1-based SetNumbers whose
CompletedAt is non-null in the latest
SessionExecution for that session on today's date.
Empty when no live-training progress has been logged for today.
Keeps per-set state out of the planning-document tree (Sessions) which
represents prescription, not actuals. */
    completedSetsBySessionExercise?: { [key: string]: { [key: string]: number[]; }; };
    /** Per-session lock state, keyed by SessionId.
Possible values: "Stable" (no active lock), "Editing" (trainer holds an editing lock),
"Live" (client has an in-progress workout lock).
Missing entries are treated as "Stable".
Populated via a single batch GetStateAsync call on the session lock service. */
    lockStateBySession?: { [key: string]: string; };
    /** Per-session lock holder, keyed by SessionId.
Possible values: "Coach" (trainer/nutritionist holds the lock) or "Client".
Null / missing when the session is in the Stable state. */
    lockHolderBySession?: { [key: string]: string; };
    /** Per-session photo list for today, keyed by SessionId.
Each value is an ordered list of photos that were saved to the session log for today's date.
Sourced from the SessionLog MongoDB document for today.
Empty dictionary when no photos have been saved for any session today (or when no active plan exists). */
    photosBySession?: { [key: string]: SessionPhotoDto[]; };
    /** Per-session diary note for today, keyed by SessionId.
Only populated for sessions whose SessionLog has a non-null, non-empty Note.
Allows the mobile client to pre-load the existing note into its textarea so a subsequent
Save does not overwrite it with null (data-loss prevention).
Empty dictionary when no session has a note today (or when no active plan exists). */
    notesBySession?: { [key: string]: string; };
    /** Per-session, per-exercise logged set values for today.
Keyed by SessionId → ExerciseExternalId → list of LoggedSetDto (one per set).
Carries actual logged values, snapshot-planned values, and the backend-computed isModified flag.
Replaces the set-number-only CompletedSetsBySessionExercise for callers that
need actual vs planned comparison.
Empty when no live-training progress has been logged for today. */
    loggedSetsBySessionExercise?: { [key: string]: { [key: string]: LoggedSetDto[]; }; };
    /** Per-session hasModifications flag for today, keyed by SessionId.
True when any set under any exercise in the session has IsModified == true in the latest log.
Missing entries are treated as false (no modifications / no log). */
    hasModificationsBySession?: { [key: string]: boolean; };
    /** Per-session completed exercise INSTANCE ids for today, keyed by SessionId. Values are
raw ExerciseId values — unlike
CompletedExerciseIdsBySession and
CompletedExerciseIdsByWorkoutAndSession (both keyed on the catalog
ExerciseExternalId), this field lets a client address
completion for one specific placement of an exercise when the same catalog exercise
appears twice in one session (standalone AND nested, or nested twice) (#877).
Union of two sources — read this before consuming the field. The value set is
the union of:
Every id in the session's CompletedExerciseInstanceIds,
carried verbatim — these already identify a single placement.
Performance-derived completion, attributed placement-exact (#938).
WorkoutExercise (the live-training-assistant side of
Performance) carries only
ExerciseExternalId plus its containing
WorkoutId — no instance id — so attribution goes through
ResolveMatchedPlacements: a
fully-logged exercise is attributed to the ONE placement its containing workout resolves to
when unambiguous; fanned out across every TIED instance when the same catalog exercise is
placed twice under the same workout (or twice standalone) — genuinely unresolvable, since
WorkoutExercise carries neither an instance id nor an order; and fanned out
across every sibling instance sharing the catalog id ONLY when attribution is genuinely
impossible (no workout in the session matches the logged placement at all). Concretely: if a
session holds catalog exercise X both standalone and nested in a REAL workout, and the
client fully logs X against that real workout via the live-training assistant, only the
NESTED instance id appears here — the standalone placement is a different, unambiguous
container and is not reported complete.
Empty dictionary when no active plan exists or no session has any completed exercise for
today. Additive alongside CompletedExerciseIdsBySession and
CompletedExerciseIdsByWorkoutAndSession, which keep their existing
catalog-keyed semantics unchanged. */
    completedExerciseInstanceIdsBySession?: { [key: string]: string[]; };
    /** Per-session, per-exercise-INSTANCE logged set values for today, sourced from live-training
Performance data. Keyed by SessionId → ExerciseId (the
per-instance identifier, NOT the catalog ExerciseExternalId)
→ list of LoggedSetDto.
Unlike LoggedSetsBySessionExercise (keyed by catalog ExerciseExternalId,
which collapses two placements of the same catalog exercise within one session —
standalone AND nested, or nested twice — onto the same entry), this field attributes
Performance data to the single placement it was actually logged against: the containing
LoggedWorkout's WorkoutId is resolved against the session's nested
TrainingWorkout ids — a match attributes the data to that nested instance, no
match (e.g. the fallback WorkoutId UpdateWorkoutEndpoint's legacy single-workout path
assigns when the client sends no WorkoutId) attributes it to the standalone instance (#885).
Additive alongside LoggedSetsBySessionExercise, which keeps its existing
catalog-keyed (and, for a dual-placement session, ambiguous) semantics unchanged for
callers that have not migrated. Empty when no live-training progress has been logged for
today. */
    loggedSetsByExerciseInstanceBySession?: { [key: string]: { [key: string]: LoggedSetDto[]; }; };
    /** Per-session, per-exercise-INSTANCE completed set numbers for today, sourced from
live-training Performance data. Keyed by SessionId → ExerciseId
→ list of 1-based SetNumbers. See LoggedSetsByExerciseInstanceBySession
remarks for why this is instance-keyed rather than catalog-keyed, and additive alongside
CompletedSetsBySessionExercise, whose existing semantics are unchanged. */
    completedSetsByExerciseInstanceBySession?: { [key: string]: { [key: string]: number[]; }; };
}

/** A photo attached to a session diary entry, as returned in PhotosBySession. */
export interface SessionPhotoDto {
    /** Canonical, permanent blob storage identity for the photo. NOT directly fetchable — the
bucket carries no public-read grant for this prefix. This is the write-path identity key,
safe to echo back unchanged on a subsequent SaveSessionPhotos call. Never render this as
an <img>/Image source; use DisplayUrl instead. */
    blobUrl?: string;
    /** Short-lived pre-signed GET URL for actually fetching the photo bytes. Expires after
MinIO:ReadUrlExpiryMinutes (default 15 minutes) — presentation-only, re-fetch
rather than persisting, caching, or echoing it back on a write. Never conflate this with
BlobUrl: submitting this value back to SaveSessionPhotos would permanently
store an expiring signature (F9 follow-up). */
    displayUrl?: string;
    /** UTC timestamp when the photo was uploaded/persisted. */
    uploadedAt?: string;
    /** Optional per-photo caption (max 500 chars). Null when none was provided. */
    note?: string | undefined;
}

/** Full training plan response for the client mobile view. Contains all published weeks enriched with completion state and muscle group data. */
export interface GetFullTrainingPlanResponse {
    /** External identifier of the training plan. */
    planId?: string;
    /** Display name of the training plan. */
    planName?: string;
    /** Plan status (Draft, Active, Completed, Archived). */
    status?: string;
    /** The Monday when Week 1 begins, if set. */
    startDate?: string | undefined;
    /** Current week number (null if plan is upcoming). */
    currentWeek?: number | undefined;
    /** Total number of weeks in the plan (including draft). */
    totalWeeks?: number;
    /** Number of published weeks. */
    publishedWeekCount?: number;
    /** Linked questionnaire response public ID, if any. */
    questionnaireResponseId?: string | undefined;
    /** When this plan was marked as completed, if applicable. */
    dateCompleted?: string | undefined;
    /** Last day of the plan's last published week, set only when the plan's coach no longer has a plan that covers
this client: after it the plan is read-only. Null otherwise. */
    runsUntil?: string | undefined;
    /** Published weeks with sessions and completion state. */
    weeks?: WeekDto[];
}

/** A published week within the training plan. */
export interface WeekDto {
    /** 1-based week number. */
    weekNumber?: number;
    /** Week publish status (Draft, Published). */
    status?: string;
    /** When this week was published. */
    datePublished?: string | undefined;
    /** Start date (Monday) of this week, computed from plan.StartDate + (weekNumber-1)*7 days.
Null when no anchor date is available. */
    weekStartDate?: string | undefined;
    /** End date (Sunday) of this week. Null when no anchor date is available. */
    weekEndDate?: string | undefined;
    /** Optional day-level notes keyed by day of week (1=Monday … 7=Sunday). */
    dayNotes?: { [key: string]: string; };
    /** Sessions in this week. */
    sessions?: SessionDto[];
}

/** A single training session within a week. */
export interface SessionDto {
    /** Unique session identifier. */
    sessionId?: string;
    /** Day of the week (1 = Monday, 7 = Sunday). */
    dayOfWeek?: number;
    /** Display name of the session (e.g. "Push Day"). */
    name?: string;
    /** Display order within the day. */
    order?: number;
    /** Optional coach notes for this session. */
    notes?: string | undefined;
    /** Number of exercises where all planned sets are completed. */
    completedExerciseCount?: number;
    /** Total number of exercises in this session. */
    totalExerciseCount?: number;
    /** Estimated session duration in minutes.
Currently null — a reliable heuristic requires product-defined set-duration
assumptions that haven't been finalised. Will be added as an additive change. */
    estimatedDurationMinutes?: number | undefined;
    /** Workouts in this session, ordered by their Order field. Every document is built directly
from Workouts and StandaloneExercises — there is no legacy
flat-exercises shape and no read-time backfill (#857). */
    workouts?: WorkoutDto[];
    /** Read-only flat union of every exercise in this session — standalone exercises plus every
workout's nested exercises — ordered by the ONE shared Order sequence workouts and
standalone exercises occupy within a session (see UpdateTrainingPlanValidator's
cross-list duplicate-Order check). Computed on read only; there is no corresponding member
on the write side, so this field is ignored (not rejected) if present in a PUT body (#874). */
    allExercises?: ExerciseDto[];
    /** Standalone exercises programmed directly on this session — not grouped under any
WorkoutDto (#857 phase 3a). Also included (in shared-Order position) in the
flat AllExercises view above and counted in TotalExerciseCount /
CompletedExerciseCount. */
    standaloneExercises?: ExerciseDto[];
    /** Current lock state of this session.
Possible values: "Stable" (no active lock), "Editing" (trainer holds an editing lock),
"Live" (client has an in-progress workout lock).
Populated via a batch GetStateAsync call on the session lock service. */
    lockState?: string;
    /** Who currently holds the lock, if any.
Possible values: "Coach", "Client", or null when the session is Stable. */
    lockHolder?: string | undefined;
    /** True when at least one exercise in this session has HasModifications == true.
Always false when no workout log exists for this session. */
    hasModifications?: boolean;
}

/** An ordered section within a session (e.g. "Hlavní", "Warm-up", "Cool-down"). */
export interface WorkoutDto {
    /** Stable identifier for this workout. */
    workoutId?: string;
    /** Display order within the session (0-based). */
    order?: number;
    /** Display name (e.g. "Hlavní", "Warm-up"). */
    name?: string;
    /** Workout format for this workout (e.g. "Emom", "Amrap", "Tabata", "ForTime").
Null means the workout uses the default Standard format. */
    format?: string | undefined;
    /** Full format-configuration object for the workout (rounds, intervals, work/rest timings).
Null when Format is null or Standard.
Mirrors WodConfig on TrainingWorkout. */
    formatConfig?: WodConfig | undefined;
    /** Optional coach note for this workout.
Mirrors the Notes property on TrainingWorkout. */
    notes?: string | undefined;
    /** True when this workout is considered complete:
            for workouts with exercises → every exercise has IsCompleted=true;
            for workouts without exercises → the workout's id is in the
            TrainingCompletion.CompletedSectionIds set for the owning session. */
    isCompleted?: boolean;
    /** Exercises within this workout. */
    exercises?: ExerciseDto[];
}

/** An exercise within a session, enriched with muscle groups and completion state. */
export interface ExerciseDto {
    /** Instance identifier for this specific exercise entry within its session — the id the
client-facing mark-complete/incomplete routes require (#857 phase 3b). Distinguishes two
occurrences of the same catalog exercise (ExerciseExternalId) programmed
twice in one workout, or once standalone and once nested in a workout of the same
session. Mirrors ExerciseId. */
    exerciseId?: string;
    /** Reference to the exercise document's ExternalId — used for exercise metadata lookups. */
    exerciseExternalId?: string;
    /** Snapshot exercise name. */
    exerciseName?: string;
    /** Display order within the session. */
    order?: number;
    /** Optional coach notes for this exercise. */
    notes?: string | undefined;
    /** Rest time between sets in seconds. */
    restSeconds?: number | undefined;
    /** Movement type — drives which set field the prescription uses
(reps / duration / distance / reps-for-time). Required for the
client to render the correct summary string. Serialised as the
enum's string name (e.g. "Reps", "Time", "Distance",
"RepsForTime"); the client casts to its `MovementType` enum.
Defaults to "Reps" when the underlying exercise carries no
explicit value. */
    movementType?: string;
    /** Target muscle groups fetched from the Exercise document.
Empty list when the exercise no longer exists in the database. */
    muscleGroups?: MuscleGroup[];
    /** True when this specific exercise instance (ExerciseId) was marked complete
directly (checkbox/instance-keyed completion), OR every planned set has a completed
workout log entry. The instance-keyed check is what lets a set-less exercise ever report
complete, and what lets two placements of the same catalog exercise
(ExerciseExternalId) in one session be completed independently (#877). */
    isCompleted?: boolean;
    /** True when at least one set under this exercise has IsModified == true.
Always false when no workout log exists for this exercise. */
    hasModifications?: boolean;
    /** Planned sets with per-set completion timestamps and actual-vs-planned delta. */
    sets?: SetDto[];
}

/** A planned set with its completion state and actual-vs-planned delta derived from workout logs. */
export interface SetDto {
    /** 1-based set number within the exercise. */
    setNumber?: number;
    /** Set type (Normal, Warmup, Dropset, Superset). */
    type?: string;
    /** Target number of repetitions (from the plan prescription). */
    reps?: number | undefined;
    /** Target weight in kilograms (from the plan prescription). */
    weightKg?: number | undefined;
    /** Target duration in seconds (from the plan prescription). */
    durationSeconds?: number | undefined;
    /** Target distance in meters (from the plan prescription). */
    distanceMeters?: number | undefined;
    /** Rest time after this set in seconds. */
    restSeconds?: number | undefined;
    /** When this set was completed, or null if not yet done. */
    completedAt?: string | undefined;
    /** Actual repetitions logged. Null when not yet performed. */
    actualReps?: number | undefined;
    /** Actual weight (kg) logged. Null when not yet performed. */
    actualWeightKg?: number | undefined;
    /** Actual RPE logged. Null when not yet performed. */
    actualRpe?: number | undefined;
    /** Actual duration (seconds) logged. Null when not yet performed. */
    actualDurationSeconds?: number | undefined;
    /** Actual distance (meters) logged. Null when not yet performed. */
    actualDistanceMeters?: number | undefined;
    /** Snapshot-planned repetitions at log time. Null for legacy logs. */
    plannedReps?: number | undefined;
    /** Snapshot-planned weight (kg) at log time. Null for legacy logs. */
    plannedWeightKg?: number | undefined;
    /** Snapshot-planned RPE at log time. Null for legacy logs. */
    plannedRpe?: number | undefined;
    /** Snapshot-planned duration (seconds) at log time. Null for legacy logs. */
    plannedDurationSeconds?: number | undefined;
    /** Snapshot-planned distance (meters) at log time. Null for legacy logs. */
    plannedDistanceMeters?: number | undefined;
    /** Backend-computed flag: true when any actual field differs from its snapshot-planned
counterpart. Always false for legacy sets (no snapshot → treated as planned == actual). */
    isModified?: boolean;
}

