    /** The currency of the amount. */
    currency?: PaymentCurrency;
    /** Day the payment falls due. */
    dueDate?: string;
    /** Status; Overdue is derived from the due date. */
    status?: ClientPaymentStatus;
    /** When the client was last asked to pay (UTC); null if never. */
