    /** Food name. */
    foodName?: string;
    /** Amount eaten in grams. */
    amountGrams?: number;
    /** Kilocalories for the eaten amount. */
    kcal?: number;
    /** Protein in grams. */
    protein?: number;
    /** Carbohydrates in grams. */
    carbs?: number;
    /** Fat in grams. */
    fat?: number;
    /** Fiber in grams. */
