/** What the client owes and has paid, grouped by coach. */
export interface GetClientPaymentsResponse {
    /** One entry per coach the client has linked payments with; empty when there are none. */
    coaches?: ClientPaymentCoachDto[];
}

/** One coach's payments as the client sees them. */
export interface ClientPaymentCoachDto {
    /** Public id of the coach's professional profile. */
    coachId?: string;
    /** The coach's name. */
    coachName?: string;
    /** Whether the client's collaboration with this coach has ended; the payments stay visible and payable. */
    collaborationEnded?: boolean;
    /** Payments the coach asked for, still unpaid (overdue ones marked), oldest due date first. */
    requested?: ClientPaymentItemDto[];
    /** Payments already paid, most recent first. */
    paid?: ClientPaymentItemDto[];
}

/** One requested or paid payment with everything the client needs to pay it. */
export interface ClientPaymentItemDto {
    /** Public id of the payment. */
    paymentId?: string;
    /** Requested, Overdue (requested and past its due date) or Paid. */
    status?: ClientPaymentStatus;
    /** Package name, or the title of a one-off payment. */
    name?: string | undefined;
    /** First day of the billing period; null for a one-off payment. */
    periodStart?: string | undefined;
    /** Last day of the billing period; null for a one-off payment. */
    periodEnd?: string | undefined;
    /** Amount in Currency. */
    amount?: number | undefined;
    /** The currency of the amounts. */
    currency?: PaymentCurrency;
    /** Package price before any discount. */
    basePrice?: number | undefined;
    /** Label of the discount behind the amount; null for a custom price (see IsCustomPrice). */
    discountLabel?: string | undefined;
    /** Whether the amount is a custom price the coach set; clients localize the wording. */
    isCustomPrice?: boolean;
    /** Day the payment falls due. */
    dueDate?: string;
    /** Day the coach confirmed the money; paid payments only. */
    paidOn?: string | undefined;
    /** Whether the payment belongs to a collaboration that ended before the current one with this coach. */
    isEarlierCollaboration?: boolean;
    /** The coach's IBAN; requested payments only. */
    iban?: string | undefined;
    /** Name of the account holder; requested payments only. */
    accountHolder?: string | undefined;
    /** Variable symbol to put on the transfer; requested payments only. */
    variableSymbol?: string | undefined;
    /** Transfer message; requested payments only. */
    message?: string | undefined;
    /** The QR Platba (SPAYD) payload to render as a QR code; requested payments only. */
    qrPayload?: string | undefined;
}

/** Server-controlled switches the client mobile app reads at start-up. */
export interface GetClientAppConfigResponse {
    /** Whether the iOS app shows the payments UI. */
    showPaymentsOnIos?: boolean;
    /** Whether the Android app shows the payments UI. */
    showPaymentsOnAndroid?: boolean;
}

export interface GetCollaborationsResponse {
    collaborations?: CollaborationDto[];
}

export interface CollaborationDto {
    publicId?: string;
    professionalPublicId?: string;
    professionalName?: string;
    professionalCity?: string | undefined;
    role?: string;
    /** Collaboration type the link covers, or null when it grants no plan view. */
    coveredType?: LinkCapabilityScope | undefined;
    since?: string;
    /** Professional's avatar URL. Falls back to the underlying user's
personal avatar when the professional-profile-specific one isn't set.
Null when neither is uploaded. */
    avatarBlobUrl?: string | undefined;
    /** First payment of the collaboration's current terms; null when the client has no terms with this professional. */
    firstPayment?: CollaborationFirstPaymentDto | undefined;
    /** Weekdays the professional's weekly check-ins reach this client; empty when none is scheduled. */
    checkIns?: CollaborationCheckInDto[];
}

/** The first payment of a collaboration's current terms. Carries no bank details; the client matches PaymentId against GET /client/payments for the QR data. */
export interface CollaborationFirstPaymentDto {
    /** Name of the package the payment is for. */
    packageName?: string | undefined;
    /** Amount of the payment, or null when it cannot be worked out. */
    amount?: number | undefined;
    /** Currency of the amount. */
    currency?: PaymentCurrency;
    /** Upcoming, Requested, Overdue, Paid or Waived. */
    status?: ClientPaymentStatus;
    /** The day the payment falls due. */
    dueDate?: string;
    /** Public id of the payment once the coach has requested it; null while it is only upcoming. */
    paymentId?: string | undefined;
}

/** The weekday a professional's weekly check-in reaches this client. */
export interface CollaborationCheckInDto {
    /** Training or Nutrition. */
    profession?: Profession;
    /** Day of the week the check-in is sent, after any per-client override. */
    dayOfWeek?: DayOfWeek;
}

export enum DayOfWeek {
    Sunday = "Sunday",
    Monday = "Monday",
    Tuesday = "Tuesday",
    Wednesday = "Wednesday",
    Thursday = "Thursday",
    Friday = "Friday",
    Saturday = "Saturday",
}

/** A coach's automation rule as returned by the management endpoints. */
export interface AutomationRuleDto {
    /** Public id of the rule. */
    ruleId?: string;
    /** Rule name. */
    name?: string;
    /** Optional text sent with the request. */
    message?: string | undefined;
    /** What the rule asks of the client. */
    actionType?: AutomationActionType;
    /** Public id of the questionnaire a SendForm rule sends. */
    questionnaireId?: string | undefined;
    /** Schedule or event trigger. */
    triggerKind?: AutomationTriggerKind;
    /** Schedule trigger: send every N units. */
    scheduleInterval?: number | undefined;
    /** Schedule trigger: unit of the interval. */
    scheduleUnit?: AutomationScheduleUnit | undefined;
    /** Client-local time of day; required for a schedule, optional for an event (09:00 when absent). */
    localTime?: string | undefined;
    /** Check-in rule: client-local weekday of the send; null for any other rule. */
    scheduleWeekday?: DayOfWeek | undefined;
    /** Check-in rule: hours the client has to answer before the week counts as missed. */
    answerWindowHours?: number | undefined;
    /** Check-in rule: hours after the send at which an unanswered check-in is reminded; null means no reminder. */
    reminderAfterHours?: number | undefined;
    /** Check-in rule: whether the coach is notified once when a week is missed. */
    notifyCoachOnMissedWeek?: boolean | undefined;
    /** Event trigger: the event. */
    eventType?: AutomationEventType | undefined;
    /** Event trigger: days between the event and the send. */
    eventOffsetDays?: number | undefined;
    /** Event trigger: whether the offset lands before or after the event. */
    eventOffsetDirection?: AutomationOffsetDirection | undefined;
    /** Plan events only: fire at most once per plan. */
    oncePerPlan?: boolean;
    /** Skip an occurrence while the previous request is still unanswered. */
    skipWhilePreviousUnanswered?: boolean;
    /** Stop after this many sends per client; null means no limit. */
    stopAfterSends?: number | undefined;
    /** Whether the rule is active. */
    enabled?: boolean;
    /** Which clients the rule applies to; All for a client-only rule. */
    audience?: AutomationAudience;
    /** The audience tag; null when the audience is not Tag, or the tag was deleted. */
    tag?: AutomationRuleTagDto | undefined;
    /** Chosen clients of a Chosen audience. */
    clients?: AutomationRuleClientDto[];
    /** Public id of the client a client-only rule belongs to; null for a global rule. */
    onlyClientId?: string | undefined;
    /** Coverage summary; filled by the list and get endpoints, null on create and update responses. */
    summary?: AutomationRuleSummaryDto | undefined;
}

/** What an automation rule asks of the client. */
export enum AutomationActionType {
    SendForm = "SendForm",
    RequestProgressPhotos = "RequestProgressPhotos",
    RequestMeasurements = "RequestMeasurements",
}

/** How an automation rule is triggered. */
export enum AutomationTriggerKind {
    Schedule = "Schedule",
    Event = "Event",
}

/** Unit of a schedule trigger's interval. */
export enum AutomationScheduleUnit {
    Days = "Days",
    Weeks = "Weeks",
}

/** Events an automation rule can fire on. Payment events are not part of this set. */
export enum AutomationEventType {
    ClientJoined = "ClientJoined",
    PlanStarted = "PlanStarted",
    PlanEnded = "PlanEnded",
    CheckInMissed = "CheckInMissed",
    ClientInactive = "ClientInactive",
    FormAnswered = "FormAnswered",
}

/** Whether an event trigger's day offset lands after or before the event. */
export enum AutomationOffsetDirection {
    After = "After",
    Before = "Before",
}

/** Which of the coach's clients a global automation rule applies to. */
export enum AutomationAudience {
    All = "All",
    Tag = "Tag",
    Chosen = "Chosen",
}

/** The audience tag of a rule. */
export interface AutomationRuleTagDto {
    /** Public id of the tag. */
    tagId?: string;
    /** Tag label. */
    name?: string;
}

/** A chosen client of a rule's audience. */
export interface AutomationRuleClientDto {
    /** Public id of the client profile. */
    clientId?: string;
    /** Client first name. */
    firstName?: string;
    /** Client last name. */
    lastName?: string;
}

/** What a rule covers across the coach's clients right now. */
export interface AutomationRuleSummaryDto {
    /** Earliest next send (UTC) across the covered clients; null when none is due or computable. */
    nextSendAt?: string | undefined;
    /** Number of covered clients the rule applies to, including those whose override disables it (only NextSendAt skips them). */
    clientCount?: number;
    /** Covered clients that have a custom override of the rule. */
    customCount?: number;
    /** Covered clients with a pause in effect. */
    pausedCount?: number;
}

/** The part of an automation rule a coach can customise per client: message, trigger and options. */
export interface AutomationTriggerBody {
    /** Optional text sent with the request (at most 1000 characters; 500 for progress photos). */
    message?: string | undefined;
    /** Schedule or event trigger. */
    triggerKind?: AutomationTriggerKind;
    /** Schedule trigger: send every N units (1-365). */
    scheduleInterval?: number | undefined;
    /** Schedule trigger: unit of the interval. */
    scheduleUnit?: AutomationScheduleUnit | undefined;
    /** Client-local time of day, from 00:00 up to 23:59. Required for a schedule trigger; optional for an
event trigger, which sends at 09:00 when it is absent. */
    localTime?: string | undefined;
    /** Check-in rule: client-local weekday of the send. Required for a check-in form, refused otherwise. */
    scheduleWeekday?: DayOfWeek | undefined;
    /** Check-in rule: hours the client has to answer before the week counts as missed (48). */
    answerWindowHours?: number | undefined;
    /** Check-in rule: hours after the send at which an unanswered check-in is reminded (24); null sends no reminder. */
    reminderAfterHours?: number | undefined;
    /** Check-in rule: whether the coach is notified once when a week is missed; null counts as false. */
    notifyCoachOnMissedWeek?: boolean | undefined;
    /** Event trigger: the event. */
    eventType?: AutomationEventType | undefined;
    /** Event trigger: days between the event and the send; defaults to 0. */
    eventOffsetDays?: number | undefined;
    /** Event trigger: whether the offset lands before or after the event; defaults to After. */
    eventOffsetDirection?: AutomationOffsetDirection | undefined;
    /** Plan events only: fire at most once per plan. */
    oncePerPlan?: boolean;
    /** Skip an occurrence while the previous request is still unanswered. */
    skipWhilePreviousUnanswered?: boolean;
    /** Stop after this many sends per client; null means no limit. */
    stopAfterSends?: number | undefined;
    /** Whether the rule is active. */
    enabled?: boolean;
}

/** The full body of an automation rule: identity, action and the customisable trigger part. */
export interface AutomationRuleBody extends AutomationTriggerBody {
    /** Rule name (required, at most 100 characters). */
    name?: string;
    /** What the rule asks of the client. */
    actionType?: AutomationActionType;
    /** Questionnaire to send; required for SendForm, ignored otherwise. */
    questionnaireId?: string | undefined;
}

/** A global rule body together with its audience ("Who"). */
export interface AutomationAudienceBody extends AutomationRuleBody {
    /** Which clients the rule applies to. Null means All on create and "leave the audience unchanged"
on update; it must be null for a client-only rule. */
    audience?: AutomationAudience | undefined;
    /** Public id of the coach's tag; required when the audience is Tag. */
    audienceTagId?: string | undefined;
    /** Public ids of the chosen clients; required (non-empty) when the audience is Chosen. */
    audienceClientIds?: string[];
}

/** Request for replacing an automation rule; the body carries the rule and, for a global rule, its audience. */
export interface UpdateAutomationRuleRequest extends AutomationAudienceBody {
}

/** Request for resetting a global rule to its default for one client. */
export interface ResetClientAutomationRequest {
}

/** Request for pausing or resuming a global rule for one client. */
export interface PauseClientAutomationRequest {
    /** True to pause, false to resume. */
    isPaused?: boolean;
    /** Last client-local day of the pause; only with IsPaused. Null pauses until resumed. */
    pausedUntil?: string | undefined;
    /** Short note about the pause (at most 200 characters); only with IsPaused. */
    pauseNote?: string | undefined;
}

/** Request for customising a global rule for one client; the body is the customised message, trigger and options. */
export interface OverrideClientAutomationRequest extends AutomationTriggerBody {
}

/** A client's effective automation rules with a 30-day summary of what was sent. */
export interface GetClientAutomationsResponse {
    /** The rules by creation order. */
    items?: ClientAutomationItem[];
    /** Totals over the last 30 days across all rules. */
    last30Days?: ClientAutomationSummary;
}

/** One row of a client's effective rule list. */
export interface ClientAutomationItem {
    /** Public id of the rule; null for a linked check-in row. */
    ruleId?: string | undefined;
    /** Where the row comes from. */
    source?: AutomationRuleSource;
    /** Rule name; null for a linked check-in row. */
    name?: string | undefined;
    /** Training or Nutrition for a linked check-in row; null for rules. */
    profession?: string | undefined;
    /** What the rule asks of the client; null for a linked check-in row. */
    actionType?: AutomationActionType | undefined;
    /** Public id of the questionnaire a SendForm rule sends. */
    questionnaireId?: string | undefined;
    /** Effective message. */
    message?: string | undefined;
    /** Effective trigger kind; null for a linked check-in row. */
    triggerKind?: AutomationTriggerKind | undefined;
    /** Effective schedule interval. */
    scheduleInterval?: number | undefined;
    /** Effective schedule unit. */
    scheduleUnit?: AutomationScheduleUnit | undefined;
    /** Effective client-local time of day; null on an event rule means 09:00. */
    localTime?: string | undefined;
    /** Effective event. */
    eventType?: AutomationEventType | undefined;
    /** Effective event offset in days. */
    eventOffsetDays?: number | undefined;
    /** Effective event offset direction. */
    eventOffsetDirection?: AutomationOffsetDirection | undefined;
    /** Effective once-per-plan flag. */
    oncePerPlan?: boolean;
    /** Effective skip-while-unanswered flag. */
    skipWhilePreviousUnanswered?: boolean;
    /** Effective send limit. */
    stopAfterSends?: number | undefined;
    /** Effective enabled flag. */
    enabled?: boolean;
    /** Whether a pause is in effect right now. */
    isPaused?: boolean;
    /** Last local day of the pause, while it is in effect. */
    pausedUntil?: string | undefined;
    /** Note of the pause, while it is in effect. */
    pauseNote?: string | undefined;
    /** Effective check-in weekday; null for a rule that is not a check-in. */
    scheduleWeekday?: DayOfWeek | undefined;
    /** Effective check-in answer window in hours. */
    answerWindowHours?: number | undefined;
    /** Effective check-in reminder delay in hours; null means no reminder. */
    reminderAfterHours?: number | undefined;
    /** Effective notify-the-coach-on-missed-week flag of a check-in. */
    notifyCoachOnMissedWeek?: boolean | undefined;
    /** Next send (UTC); null when paused, disabled, or an event other than plan started or ended. */
    nextSendAt?: string | undefined;
    /** The most recent run; null until a run exists. */
    lastResult?: ClientAutomationLastResult | undefined;
    /** Requests sent in the last 30 days. */
    sent30Days?: number;
    /** Requests answered in the last 30 days. */
    answered30Days?: number;
    /** Occurrences skipped in the last 30 days. */
    skipped30Days?: number;
}

/** Where a rule in a client's effective list comes from. */
export enum AutomationRuleSource {
    Default = "Default",
    Custom = "Custom",
    Paused = "Paused",
    OnlyThisClient = "OnlyThisClient",
    Linked = "Linked",
}

/** The most recent run of a rule for the client. */
export interface ClientAutomationLastResult {
    /** Outcome. */
    status?: AutomationRunStatus;
    /** Why it was skipped. */
    skipReason?: AutomationSkipReason | undefined;
    /** When it was sent (UTC). */
    sentAt?: string | undefined;
    /** When the client answered (UTC). */
    answeredAt?: string | undefined;
}

/** Outcome of one automation occurrence for one client. */
export enum AutomationRunStatus {
    Sent = "Sent",
    Skipped = "Skipped",
    Failed = "Failed",
}

/** Why an automation occurrence was skipped. */
export enum AutomationSkipReason {
    PreviousUnanswered = "PreviousUnanswered",
    Paused = "Paused",
    StopAfterReached = "StopAfterReached",
    AlreadySentForPlan = "AlreadySentForPlan",
}

/** Totals over the last 30 days. */
export interface ClientAutomationSummary {
    /** Requests sent. */
    sent?: number;
    /** Requests answered. */
    answered?: number;
    /** Requests sent and still waiting for an answer. */
    waiting?: number;
    /** Occurrences skipped. */
    skipped?: number;
}

/** Request for a client's effective automation rules. */
export interface GetClientAutomationsRequest {
}

/** The caller's global automation rules. */
export interface GetAutomationRulesResponse {
    /** Global rules, oldest first. */
    rules?: AutomationRuleDto[];
    /** Always empty: the weekly check-in is an ordinary rule now. Kept so the generated clients keep compiling. */
    linkedCheckIns?: AutomationLinkedCheckInDto[];
}

/** The weekly check-in of one profession as a linked, read-only entry among the global rules. It names no weekday and no time. */
export interface AutomationLinkedCheckInDto {
    /** The profession the check-in belongs to. */
    profession?: Profession;
    /** Whether the coach's check-in is enabled. */
    enabled?: boolean;
    /** Covered clients with the check-in enabled, after per-client overrides. */
    clientCount?: number;
}

/** Request for one automation rule. */
export interface GetAutomationRuleRequest {
}

/** Request for deleting an automation rule. */
export interface DeleteAutomationRuleRequest {
}

/** Request for adding a rule that applies to one client only. It carries no audience. */
export interface CreateClientAutomationRuleRequest extends AutomationRuleBody {
}

/** Request for creating a global automation rule; the body carries the rule and its audience. */
export interface CreateAutomationRuleRequest extends AutomationAudienceBody {
}

/** Response returned after an email address has been verified. */
export interface VerifyEmailResponse {
    /** Human-readable confirmation message. */
    message?: string;
    /** The verified email address. */
    email?: string;
    /** First name of the verified account. */
    firstName?: string;
    /** Roles held by the verified account. */
    roles?: string[];
}

/** Request model for email verification. */
export interface VerifyEmailRequest {
    /** The verification token from the email link. */
    token?: string;
}

/** Response body for POST /auth/social/nonce. */
export interface RequestNonceResponse {
    /** The raw nonce value to embed in the Apple/Google sign-in flow.
Apple expects SHA-256(nonce) in the id_token; Google expects the raw value. */
    nonce?: string;
}

/** Response returned after a successful Google social login. Shape is intentionally identical to LoginResponse so clients can reuse the same token-storage logic. */
export interface GoogleSocialLoginResponse {
    /** JWT access token (short-lived, 15 minutes). */
    accessToken?: string;
    /** Refresh token for obtaining new access tokens (7 days). */
    refreshToken?: string;
    /** Access token expiration time in UTC. */
    expiresAt?: string;
    /** Whether the user's email address has been verified.
Always true for Google-provisioned accounts because Google
verifies the email before issuing the ID token. */
    emailConfirmed?: boolean;
}

/** Request body for POST /auth/social/google. */
export interface GoogleSocialLoginRequest {
    /** The Google ID token returned by the Google Identity Services flow on the client. */
    idToken: string;
    /** The raw nonce value obtained from POST /auth/social/nonce.
The client must pass the same raw value that was embedded in the Google sign-in flow
(Google embeds the raw nonce directly in the id_token's nonce field — no hashing). */
    nonce: string;
    /** Roles requested for a brand-new account: Trainer, Nutritionist or Client (never combined with a coach role).
Empty or absent means Client. Ignored when the Google identity is already linked to an account. */
    roles?: string[];
    /** Art. 9 health-data consent. Must be true when a new Client account is created and
must be absent for a coach sign-up. Ignored when the Google identity is already linked. */
    healthDataConsent?: boolean | undefined;
}

/** Response returned on a successful Apple Sign-In. Identical shape to Google Social Login response. */
export interface AppleSocialLoginResponse {
    /** Short-lived JWT access token (15 minutes by default). */
    accessToken?: string;
    /** Long-lived opaque refresh token (7 days by default). */
    refreshToken?: string;
    /** UTC expiry time of the access token. */
    expiresAt?: string;
    /** Whether the account's email address has been confirmed.
Apple-provisioned and Apple-verified accounts always have this set to true,
which causes the client to redirect to /download-app rather than /verify-email. */
    emailConfirmed?: boolean;
}

/** Request body for the Apple Sign-In endpoint. The identity token is always required. The authorization code and name fields are only present on first authorization (Apple omits them on re-auth). */
export interface AppleSocialLoginRequest {
    /** The Apple identity token (JWT) returned by the Apple JS SDK or native Sign-In. */
    identityToken: string;
    /** The authorization code returned by Apple (forwarded for forward-compatibility).
The backend does not currently exchange this for tokens — identity verification
is performed via the identity token alone. */
    authorizationCode?: string | undefined;
    /** The user's first name, present only on first authorization.
Apple does not re-send this on subsequent authentications. */
    firstName?: string | undefined;
    /** The user's last name, present only on first authorization.
Apple does not re-send this on subsequent authentications. */
    lastName?: string | undefined;
    /** The raw nonce value obtained from POST /auth/social/nonce.
The client must pass the same raw value that was embedded in the Apple sign-in flow
(Apple hashes it before embedding: SHA-256(nonce) appears in the id_token's nonce claim). */
    nonce: string;
    /** Roles requested for a brand-new account: Trainer, Nutritionist or Client (never combined with a coach role).
Empty or absent means Client. Ignored when the Apple identity is already linked to an account. */
    roles?: string[];
    /** Art. 9 health-data consent. Must be true when a new Client account is created and
must be absent for a coach sign-up. Ignored when the Apple identity is already linked. */
    healthDataConsent?: boolean | undefined;
}

/** Request model for completing a password reset using a token. */
export interface ResetPasswordRequest {
    /** The password reset token received via email. */
    token: string;
    /** The user's email address. */
    email: string;
    /** The new password. */
    newPassword: string;
    /** Confirmation of the new password. */
    confirmPassword: string;
}

/** Request model for initiating a password reset. */
export interface RequestPasswordResetRequest {
    /** Email address of the account to reset. */
    email: string;
}

/** Response model returned after successful registration. */
export interface RegisterResponse {
    /** The newly created user's public ID. */
    userId?: string;
    /** The user's email address. */
    email?: string;
    /** Confirmation message. */
    message?: string;
}

/** Request model for user registration. */
export interface RegisterRequest {
    /** User's email address (used as login). */
    email: string;
    /** User's chosen password. */
    password: string;
    /** Password confirmation (must match Password). */
    confirmPassword: string;
    /** User's first name. */
    firstName: string;
    /** User's last name. */
    lastName: string;
    /** The roles the user is registering as. Must contain at least one of: Trainer, Nutritionist, Client. */
    roles: string[];
    /** Explicit GDPR consent for personal data processing (Art. 6 GDPR). Required for all roles. */
    gdprConsent?: boolean;
    /** Explicit consent for processing health data under GDPR Art. 9.
Must be true for the Client role; must be null for Trainer and Nutritionist roles. */
    healthDataConsent?: boolean | undefined;
}

/** Response model returned after successful token refresh. */
export interface RefreshTokenResponse {
    /** New JWT access token. */
    accessToken?: string;
    /** New refresh token (old one is invalidated via rotation). */
    refreshToken?: string;
    /** New access token expiration time in UTC. */
    expiresAt?: string;
}

/** Request model for refreshing an access token using a refresh token. */
export interface RefreshTokenRequest {
    /** The current refresh token to exchange for a new token pair. */
    refreshToken: string;
}

/** Request model for logging out (revoking a refresh token). */
export interface LogoutRequest {
    /** The refresh token to revoke. */
    refreshToken?: string;
}

/** Response model returned after successful login. */
export interface LoginResponse {
    /** JWT access token (short-lived, 15 minutes). */
    accessToken?: string;
    /** Refresh token for obtaining new access tokens (7 days). */
    refreshToken?: string;
    /** Access token expiration time in UTC. */
    expiresAt?: string;
    /** Whether the user's email address has been verified. */
    emailConfirmed?: boolean;
}

/** Request model for user login. */
export interface LoginRequest {
    /** User's email address. */
    email: string;
    /** User's password. */
    password: string;
}

/** Result of changing the email address of an unverified account. */
export interface ChangeUnverifiedEmailResponse {
    /** The address the verification email was sent to. */
    email?: string;
    /** How many more verification emails can be requested for this account. */
    remainingResends?: number;
}

/** Request for changing the email address of an unverified account. */
export interface ChangeUnverifiedEmailRequest {
    /** The corrected email address. */
    newEmail: string;
}

/** Response model for an anonymous resend-verification request. Deliberately generic — the same message is returned regardless of whether the email is registered, already verified, or has hit its resend cap, so the response body never becomes an account-existence oracle. */
export interface AnonymousResendVerificationResponse {
    /** Generic, state-independent confirmation message. */
    message?: string;
}

/** Request model for requesting a verification-email resend by email address, without an authenticated session. */
export interface AnonymousResendVerificationRequest {
    /** Email address of the account to resend a verification email for. */
    email: string;
}

/** Response model returned after successfully accepting an invitation. */
export interface AcceptInvitationResponse {
    /** Confirmation message. */
    message?: string;
    /** Public identifier of the trainer whose invitation was accepted. */
    trainerPublicId?: string;
}

/** Request model for accepting a trainer's invitation. */
export interface AcceptInvitationRequest {
    /** The one-time invitation token received from the trainer. */
    token: string;
}

export class ApiException extends Error {
    override message: string;
    status: number;
    response: string;
    headers: { [key: string]: any; };
    result: any;

    constructor(message: string, status: number, response: string, headers: { [key: string]: any; }, result: any) {
        super();

        this.message = message;
        this.status = status;
        this.response = response;
        this.headers = headers;
        this.result = result;
    }

    protected isApiException = true;

    static isApiException(obj: any): obj is ApiException {
        return obj.isApiException === true;
    }
}

function throwException(message: string, status: number, response: string, headers: { [key: string]: any; }, result?: any): any {
    if (result !== null && result !== undefined)
        throw result;
    else
        throw new ApiException(message, status, response, headers, null);
}

function isAxiosError(obj: any): obj is AxiosError {
    return obj && obj.isAxiosError === true;
}